use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.board();
    var first = true;
    for dish in board {
        if !first {
            io.write(text: ";")?;
        }
        kitchen.serve(dish: dish)?;
        first = false;
    }
    return Ok(unit);
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    let len = board.len();
    while i < len {
        if i > 0 {
            io.write(text: ";")?;
        }
        galley.kitchen.serve(dish: board.get(index: i))?;
        i = i + 1;
    }
    return Ok(unit);
}

