use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    let mut labels = [];
    for plank in planks {
        if rules.should_keep(plank: plank) {
            labels.push(rules.render_label(plank: plank));
        }
    }
    labels.join(separator: ",")
}

