use harbor.signal;

fn entries() -> String {
    let signals = signal.day_signals();
    let mut result = "";
    var first = true;
    for s in signals {
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
    }
    result
}

use harbor.signal;

pub fn entries() -> String {
