            Fog(density) => "fog:".concat(other: density),
        };
        if i == 0 {
            result = rendered;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
        i = i + 1;
    }
    result
}

use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = herd.lineup();
    var entries = List<Text>::new();
    for pony in lineup {
        herd.feed(pony: pony, scoops: 3);
        let entry = ledger.render(pony: pony);
        entries.push(entry);
    }
    let joined = entries.join(separator: ",");
    io.write(text: joined)?;
    return Ok(unit);
}

use stable.herd as herd;
use stable.ledger as ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = herd.lineup();
    var entries = Array::new();
    var i = 0;
    while i < lineup.len() {
        let pony = lineup.get(index: i);
        herd.feed(pony: pony, scoops: 3);
        let entry = ledger.render(pony: pony);
        entries.append(entry);
        i = i + 1;
    }
    let joined = entries.join(separator: ",");
    io.write(text: joined)?;
    return Ok(unit);
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var output = "";
    var i = 0;
    while i < lineup.len() {
        let pony = lineup.get(index: i);
        stable.herd.feed(pony: pony, scoops: 3);
        let entry = stable.ledger.render(pony: pony);
        if i > 0 {
            output = output.concat(other: ",");
        }
        output = output.concat(other: entry);
        i = i + 1;
    }
    io.write(text: output)?;
    return Ok(unit);
}
